 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) != 2:
        return [row[:] for row in grid]
    # The marker attached to the colored pattern is its anchor; the isolated
    # marker is the destination. Find the anchor's 4-connected component.
    def component(start):
        seen = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr,nc) not in seen:
                    seen.add((nr,nc)); q.append((nr,nc))
        return seen
    comps = [(m, component(m)) for m in markers]
    anchor, cells = max(comps, key=lambda mc: len(mc[1]))
    dest = markers[1] if markers[0] == anchor else markers[0]
    out = [row[:] for row in grid]
    dr, dc = dest[0]-anchor[0], dest[1]-anchor[1]
    out[dest[0]][dest[1]] = 0
    for r, c in cells:
        if (r,c) == anchor:
            continue
        nr, nc = r+dr, c+dc
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = grid[r][c]
    return out
